/bin/bash -lc "cat > lib/bookStore.js <<'EOF'
import { randomUUID } from 'node:crypto';
import { mkdir, readFile, rename, writeFile } from 'node:fs/promises';
import { dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const booksFilePath = fileURLToPath(new URL('../data/books.json', import.meta.url));
let mutationQueue = Promise.resolve();

async function ensureBooksFile() {
  await mkdir(dirname(booksFilePath), { recursive: true });

  try {
    await readFile(booksFilePath, 'utf8');
  } catch (error) {
    if (error?.code === 'ENOENT') {
      await writeFile(booksFilePath, '[]\\n', 'utf8');
      return;
    }

    throw error;
  }
}

async function readBooks() {
  await ensureBooksFile();
  const contents = await readFile(booksFilePath, 'utf8');

  let parsed;
  try {
    parsed = JSON.parse(contents || '[]');
  } catch {
    throw new Error('data/books.json contains invalid JSON');
  }

  if ("'!Array.isArray(parsed)) {
    throw new Error('"'data/books.json must contain a JSON array');
  }

  return parsed;
}

async function writeBooks(books) {
  const json = "'`${JSON.stringify(books, null, 2)}'"\\n"'`;
  const tempPath = `${booksFilePath}.tmp`;

  await writeFile(tempPath, json, '"'utf8');
  await rename(tempPath, booksFilePath);
}

function queueMutation(task) {
  const run = mutationQueue.then(task, task);
  mutationQueue = run.then(
    () => undefined,
    () => undefined
  );

  return run;
}

function sortBooksNewestFirst(books) {
  return [...books].sort((left, right) => {
    const leftDate = left.finishedAt ?? left.addedAt;
    const rightDate = right.finishedAt ?? right.addedAt;
    return rightDate.localeCompare(leftDate);
  });
}

export async function initializeStore() {
  await ensureBooksFile();
}

export async function listBooks() {
  const books = await readBooks();
  return sortBooksNewestFirst(books);
}

export async function getBookById(id) {
  const books = await readBooks();
  return books.find((book) => book.id === id) ?? null;
}

export async function addBook({ title, author, notes }) {
  return queueMutation(async () => {
    const books = await readBooks();
    const now = new Date().toISOString();

    const book = {
      id: randomUUID(),
      title,
      author,
      notes,
      status: 'reading',
      addedAt: now,
      finishedAt: null,
    };

    books.push(book);
    await writeBooks(books);

    return book;
  });
}

export async function markBookAsFinished(id) {
  return queueMutation(async () => {
    const books = await readBooks();
    const index = books.findIndex((book) => book.id === id);

    if (index === -1) {
      return null;
    }

    const current = books[index];
    if (current.status "'!== '"'finished') {
      books[index] = {
        ...current,
        status: 'finished',
        finishedAt: new Date().toISOString(),
      };

      await writeBooks(books);
    }

    return books[index];
  });
}
EOF

cat > server.js <<'EOF'
import http from 'node:http';
import { URL } from 'node:url';

import {
  addBook,
  getBookById,
  initializeStore,
  listBooks,
  markBookAsFinished,
} from './lib/bookStore.js';

const HOST = process.env.HOST ?? '0.0.0.0';
const PORT = Number(process.env.PORT ?? '3000');
const MAX_FORM_BODY_SIZE = 1024 * 1024;

function escapeHtml(value) {
  return String(value)
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('\"', '&quot;')
    .replaceAll(\"'\", '&#39;');
}

function formatNotes(notes) {
  if ("'!notes.trim()) {
    return '"'<em>No notes yet.</em>';
  }

  return escapeHtml(notes).replaceAll('\\n', '<br>');
}

function bookPath(id) {
  return "'`/books/${encodeURIComponent(id)}`;
}

function renderLayout(title, body) {
  return `<!doctype html>
<html lang="en">
  <head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>${escapeHtml(title)}</title>
    <style>
      :root { color-scheme: light dark; }
      body {
        font-family: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        max-width: 920px;
        margin: 2rem auto;
        padding: 0 1rem;
        line-height: 1.5;
      }
      h1, h2 { margin-bottom: 0.5rem; }
      .muted { color: #666; }
      .stack > * + * { margin-top: 1rem; }
      .panel {
        border: 1px solid #7774;
        border-radius: 8px;
        padding: 1rem;
      }
      form.stack label {
        display: block;
        font-weight: 600;
      }
      input, textarea, button {
        font: inherit;
      }
      input, textarea {
        width: 100%;
        margin-top: 0.25rem;
        border-radius: 6px;
        border: 1px solid #8885;
        padding: 0.5rem;
      }
      textarea { min-height: 100px; resize: vertical; }
      button {
        border-radius: 6px;
        border: 1px solid #8886;
        padding: 0.45rem 0.75rem;
        cursor: pointer;
      }
      ul.clean { list-style: none; padding: 0; margin: 0; }
      ul.clean > li {
        border: 1px solid #7774;
        border-radius: 8px;
        padding: 0.75rem;
      }
      ul.clean > li + li { margin-top: 0.75rem; }
      .row {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 1rem;
      }
      .flash {
        padding: 0.75rem;
        border-radius: 6px;
        border: 1px solid #2a8d5f66;
        background: #2a8d5f22;
      }
      .error {
        border-color: #b7424266;
        background: #b7424222;
      }
      .meta { margin: 0; font-size: 0.95rem; }
      .empty { font-style: italic; color: #666; }
    </style>
  </head>
  <body>
    ${body}
  </body>
</html>`;
}

function sendHtml(response, statusCode, html) {
  response.writeHead(statusCode, {
    '"'Content-Type': 'text/html; charset=utf-8',
    'Cache-Control': 'no-store',
  });
  response.end(html);
}

function redirect(response, location) {
  response.writeHead(303, { Location: location });
  response.end();
}

async function parseUrlEncodedBody(request) {
  const chunks = [];
  let totalBytes = 0;

  for await (const chunk of request) {
    totalBytes += chunk.length;
    if (totalBytes > MAX_FORM_BODY_SIZE) {
      throw new Error('Form payload too large');
    }
    chunks.push(chunk);
  }

  const bodyText = Buffer.concat(chunks).toString('utf8');
  return new URLSearchParams(bodyText);
}

function renderBookItem(book, showFinishButton) {
  return "'`<li>
    <div class="row">
      <div>
        <a href="${bookPath(book.id)}"><strong>${escapeHtml(book.title)}</strong></a>
        <p class="meta">by ${escapeHtml(book.author)}</p>
      </div>
      ${
        showFinishButton
          ? `<form method="post" action="${bookPath(book.id)}/finish">
              <button type="submit">Mark as finished</button>
            </form>`
          : '"''
      }
    </div>
  </li>"'`;
}

function renderHomePage(books, flashMessage, errorMessage) {
  const readingBooks = books.filter((book) => book.status !== '"'finished');
  const finishedBooks = books.filter((book) => book.status === 'finished');

  return renderLayout(
    'My Books',
    "'`<header>
       <h1>My Reading Tracker</h1>
       <p class="muted">Track what you are reading and what you have finished.</p>
     </header>

     ${
       flashMessage
         ? `<p class="flash">${escapeHtml(flashMessage)}</p>`
         : errorMessage
           ? `<p class="flash error">${escapeHtml(errorMessage)}</p>`
           : '"''
     }

     <section class=\"panel\">
       <h2>Add a book</h2>
       <form class=\"stack\" method=\"post\" action=\"/books\">
         <label>
           Title
           <input name=\"title\" required maxlength=\"200\" />
         </label>

         <label>
           Author
           <input name=\"author\" required maxlength=\"200\" />
         </label>

         <label>
           Notes
           <textarea name=\"notes\" maxlength=\"5000\" placeholder=\"Anything you want to remember...\"></textarea>
         </label>

         <div>
           <button type=\"submit\">Add book</button>
         </div>
       </form>
     </section>

     <section class=\"panel stack\">
       <h2>Currently reading</h2>
       "'${
         readingBooks.length > 0
           ? `<ul class="clean">${readingBooks.map((book) => renderBookItem(book, true)).join('"'')}</ul>"'`
           : '"'<p class=\"empty\">No books in progress yet.</p>'
       }
     </section>

     <section class=\"panel stack\">
       <h2>Finished</h2>
       "'${
         finishedBooks.length > 0
           ? `<ul class="clean">${finishedBooks.map((book) => renderBookItem(book, false)).join('"'')}</ul>"'`
           : '"'<p class=\"empty\">No finished books yet.</p>'
       }
     </section>"'`
  );
}

function inferBaseUrl(request) {
  const forwardedProtocol = request.headers['"'x-forwarded-proto'];
  const protocol = typeof forwardedProtocol === 'string'
    ? forwardedProtocol.split(',')[0].trim()
    : 'http';
  const host = request.headers.host ?? "'`localhost:${PORT}`;
  return `${protocol}://${host}`;
}

function renderBookPage(book, request) {
  const shareUrl = `${inferBaseUrl(request)}${bookPath(book.id)}`;

  return renderLayout(
    book.title,
    `<p><a href="/">← Back to books</a></p>

     <article class="panel stack">
       <h1>${escapeHtml(book.title)}</h1>
       <p class="meta"><strong>Author:</strong> ${escapeHtml(book.author)}</p>
       <p class="meta"><strong>Status:</strong> ${escapeHtml(book.status)}</p>
       <p class="meta"><strong>Added:</strong> ${escapeHtml(new Date(book.addedAt).toLocaleString())}</p>
       ${
         book.finishedAt
           ? `<p class="meta"><strong>Finished:</strong> ${escapeHtml(new Date(book.finishedAt).toLocaleString())}</p>`
           : '"''
       }

       <section>
         <h2>Notes</h2>
         <p>"'${formatNotes(book.notes)}</p>
       </section>

       <section>
         <h2>Share link</h2>
         <p><a href="${escapeHtml(shareUrl)}">${escapeHtml(shareUrl)}</a></p>
       </section>

       ${
         book.status !== '"'finished'
           ? "'`<form method="post" action="${bookPath(book.id)}/finish">
                <button type="submit">Mark as finished</button>
              </form>`
           : '"''
       }
     </article>"'`
  );
}

function renderNotFoundPage() {
  return renderLayout(
    '"'Not Found',
    "'`<h1>Not Found</h1>
     <p>That book does not exist.</p>
     <p><a href="/">Go back home</a></p>`
  );
}

function renderErrorPage() {
  return renderLayout(
    '"'Something went wrong',
    "'`<h1>Something went wrong</h1>
     <p>Please try again in a moment.</p>
     <p><a href="/">Go back home</a></p>`
  );
}

function extractBookId(pathname) {
  const match = pathname.match(/''^'"\\/books\\/(["'^/]+)$/);
  if (!match) {
    return null;
  }

  try {
    return decodeURIComponent(match[1]);
  } catch {
    return null;
  }
