327	    return;
328	  }
329	
330	  if (request.method === 'POST' && pathname === '/books') {
331	    const formData = await parseUrlEncodedBody(request);
332	    const title = formData.get('title')?.toString().trim() ?? '';
333	    const author = formData.get('author')?.toString().trim() ?? '';
334	    const notes = formData.get('notes')?.toString().trim() ?? '';
335	
336	    if (!title || !author) {
337	      const errorMessage = encodeURIComponent('Title and author are required.');
